insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 9', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B9.1.1.1', 'Show an understanding of formation of binary chemical compounds and their uses (Acids, Bases and Salts)', 'B9.1.1.1.1', 'Identify by name binary chemical compounds and discuss their uses', '1. Identify and name chemical compounds from a collection of materials commonly found at home, school and the community such as table salt, water, vinegar, fuel (take precaution), soap, detergents, marble and fertilisers.; 2. Write the chemical symbols of the elements identified in the chemical compounds.', 10),
('Basic 9', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B9.1.1.1', 'Show an understanding of formation of binary chemical compounds and their uses (Acids, Bases and Salts)', 'B9.1.1.1.2', 'Discuss the formation of binary chemical compounds', '1. Distinguish among elements, molecules, ions and compounds.; 2. Write molecular formula of binary compounds and describe their formation.; 3. Compare and contrast different binary chemical compounds based on their composition and properties.; 4. Form models to represent chemical compounds such as water, carbon (IV) oxide, iron (II) sulphide and magnesium oxide.', 20),
('Basic 9', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B9.1.1.1', 'Show an understanding of formation of binary chemical compounds and their uses (Acids, Bases and Salts)', 'B9.1.1.1.3', 'Describe the characteristics of common acids, bases and salts', '1. Identify acids, bases and salts by their characteristics.; 2. Create a model of a pH Scale and use it to determine the strength of common acids and alkali solutions using indicators.', 30),
('Basic 9', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B9.1.1.2', 'Demonstrate knowledge of atomic bonding in the formation of chemical compounds', 'B9.1.1.2.1', 'Recognise that chemical bond results from the attraction between atoms in a compound', '1. Identify types of inter-atomic bonds.; 2. Describe the formation of inter-atomic bonds.; 3. Identify examples of substances that exhibit ionic, covalent and metallic bonding.', 40),
('Basic 9', 'Science', 'science', 'Diversity of Matter', 'Living Cells', 'B9.1.2.1', 'Demonstrate knowledge of specialist cells of dicotyledonous plants and humans, their formation and functions for the existence of the plants and humans', 'B9.1.2.1.1', 'Discuss the concepts of specialised cells and how they are formed in dicotyledonous plants and humans', '1. Brainstorm to bring out the meaning of specialised cells.; 2. Discuss how specialised cells are formed in dicotyledonous plants and humans.', 50),
('Basic 9', 'Science', 'science', 'Diversity of Matter', 'Living Cells', 'B9.1.2.1', 'Demonstrate knowledge of specialist cells of dicotyledonous plants and humans, their formation and functions for the existence of the plants and humans', 'B9.1.2.1.2', 'Examine the functions of specialised cells in dicotyledonous plants such as epidermal, guard cells, cambium, xylem in relation to the existence of the plants', '1. Observe specialised dicotyledonous plant cells such as epidermal, guard cells, cambium, xylem from videos and charts and identify them by their names and shapes.; 2. Search from books and the internet for information on the functions of the specialised cells of dicotyledonous plants and how they relate to the existence of the plants.', 60),
('Basic 9', 'Science', 'science', 'Diversity of Matter', 'Living Cells', 'B9.1.2.1', 'Demonstrate knowledge of specialist cells of dicotyledonous plants and humans, their formation and functions for the existence of the plants and humans', 'B9.1.2.1.3', 'Examine the functions of specialised animal cells such as (nerve, blood cells, muscle cells and sperm cells) in relation to the existence of humans', '1. Observe specialised animal cells such as nerve cells, blood cells, muscle cells and sperm cells from pictures, videos and charts and identify them by their names and make models to represent their shapes.; 2. Search from books, journals and internet for information on specialised cells in exemplar 1 and how they relate to the existence of humans.', 70),
('Basic 9', 'Science', 'science', 'Cycles', 'Earth Sciences', 'B9.2.1.1', 'Demonstrate an understanding of the Nitrogen cycle as a repeated pattern of change in nature, and how it relates to the environment', 'B9.2.1.1.1', 'Explain the process of the nitrogen cycle as a repeated pattern in nature', '1. Identify the nitrogen cycle from the internet, charts, or pictures.; 2. Explain the nitrogen cycle depicting processes such as: – Nitrogen fixation – Nitrification (converting ammonia into nitrates). – Assimilation (plants and animals using nitrogen) – Ammonification (adding organic nitrogen compounds to ammonia or ammonia formation). – De-nitrification.; 3. Explain the relationship between the nitrogen cycle and the environment.; 4. Explain why the nitrogen cycle is a repeated pattern in nature.', 80),
('Basic 9', 'Science', 'science', 'Cycles', 'Earth Sciences', 'B9.2.1.1', 'Demonstrate an understanding of the Nitrogen cycle as a repeated pattern of change in nature, and how it relates to the environment', 'B9.2.1.1.2', 'Describe the importance of the nitrogen cycle to the environment', '1. Describe the importance of nitrogen to the environment.; 2. Carry out a project to show how certain plants such as leguminous crops can replenish nitrogen in the soil.; 3. Predict what will happen if the nitrogen cycle is interrupted by actions such as leaching, bush burning, and destruction of leguminous plants.', 90),
('Basic 9', 'Science', 'science', 'Cycles', 'Life Cycle of Organisms', 'B9.2.2.1', 'Demonstrate an understanding of the life cycle of grasshopper and assess how their activities affect humans', 'B9.2.2.1.1', 'Describe the life cycle of the grasshopper as a form of incomplete metamorphosis', '1. Draw the stages of the life cycle of a grasshopper from egg through nymph to adult.; 2. Identify the behaviour of each stage of the life cycle of a grasshopper.; 3. Explain why the life cycle of the grasshopper is described as incomplete metamorphosis as compared to complete metamorphosis in the housefly and mosquito in', 100),
('Basic 9', 'Science', 'science', 'Cycles', 'Life Cycle of Organisms', 'B9.2.2.1', 'Demonstrate an understanding of the life cycle of grasshopper and assess how their activities affect humans', 'B9.2.2.1.2', 'Examine how the activities of the grasshopper affect humans', '1. Outline the activities of the grasshopper in everyday life (e.g. feeding on grasses and weeds.).; 2. Carry out a search for information on activities of the grasshopper that are harmful or beneficial to humans.; 3. Generate activities to promote or reduce the effect of the activities of grasshoppers on humans.', 110),
('Basic 9', 'Science', 'science', 'Cycles', 'Crop Production', 'B9.2.3.1', 'Show an understanding of differences in maturities of different crops grown in different soils and different seed beds', 'B9.2.3.1.1', 'Observe and describe differences in maturation of crops grown in different soils and on different seed beds', '1. Observe and record the maturity stages of different crops grown in different soils and seed beds.; 2. Discuss the differences in maturity stages among the different crops on the different soils and seed beds.; 3. Compare and contrast the maturity stages of crops and seedlings in the community/school garden with others grown elsewhere.', 120),
('Basic 9', 'Science', 'science', 'Cycles', 'Crop Production', 'B9.2.3.2', 'Demonstrate knowledge and understanding of uses of different crops at different maturity stages', 'B9.2.3.2.1', 'Observe and record the uses of different crops at different maturity stages', '1. Discuss and write the uses of each maturity stage of each crop identified.; 2. Categorise crops by their different maturity stages and uses.', 130),
('Basic 9', 'Science', 'science', 'Cycles', 'Crop Production', 'B9.2.3.2', 'Demonstrate knowledge and understanding of uses of different crops at different maturity stages', 'B9.2.3.2.2', 'Evaluate the importance of knowledge of the maturity stages of different crops to human beings', '1. Explain the specific use(s) of each maturity stage of different crops to humans, other crops, animals, and the environment.; 2. Explain how the knowledge of the maturity stages of different crops helps a farmer in crop selection, time of harvest, and others.; 3. Compare different stages of maturity of crops identified in the community with those used in other places.', 140),
('Basic 9', 'Science', 'science', 'Cycles', 'Animal Production', 'B9.2.4.1', 'Demonstrate understanding of the preparation of feed for domestic and commercial animals', 'B9.2.4.1.1', 'List the ingredients and the method of preparation of different feed for different domestic and commercial animals', '1. Demonstrate how farmers prepare feed for different domestic and commercial animals with ingredients.; 2. Write down the process of preparing feed for different domestic and commercial animals with the ingredients.; 3. Compile a table, matching feed, ingredients and method of preparation.; 4. Formulate and prepare feed for domestic and commercial animals.', 150),
('Basic 9', 'Science', 'science', 'Cycles', 'Animal Production', 'B9.2.4.2', 'Demonstrate skills and knowledge of feeding domestic and commercial animals', 'B9.2.4.2.1', 'Describe and select appropriate feed for different domestic and commercial animals', '1. Compile a list of feed commonly consumed by the different domestic and commercial animals in the environment.; 2. Compare and contrast the characteristics of different kinds of feed commonly consumed by categories of domestic and commercial animals (ruminants, monogastrics, and poultry).; 3. Record feed used to feed domestic and commercial animals on farms over a period of time.; 4. Identify named samples of feed for three categories of domestic and commercial animals (ruminants, monogastrics, and poultry).', 160),
('Basic 9', 'Science', 'science', 'Cycles', 'Animal Production', 'B9.2.4.2', 'Demonstrate skills and knowledge of feeding domestic and commercial animals', 'B9.2.4.2.2', 'Differentiate between different types of feed for different stages of domestic and commercial animals', '1. Categorise different types of animals according to their stages of growth (young, growing and matured stages).; 2. List the types of feed used for the various stages of growth in their domestic and commercial ruminants, monogastrics and poultry.; 3. Compare and construct the major functions of feed in each growth stage of different animals.; 4. Discuss types of feed used to feed different domestic and commercial animals at different stages of growth.', 170),
('Basic 9', 'Science', 'science', 'Cycles', 'Animal Production', 'B9.2.4.2', 'Demonstrate skills and knowledge of feeding domestic and commercial animals', 'B9.2.4.2.3', 'Perform the feeding of domestic and commercial animals', '1. Demonstrate how to feed domestic and commercial animals at different stages of growth and production, with appropriate feed in the school farm or a farm in the community.', 180),
('Basic 9', 'Science', 'science', 'Systems', 'The Human Body System', 'B9.3.1.1', 'Demonstrate understanding of the blood circulatory system, health problems associated with the system and its relationship with the respiratory system in humans', 'B9.3.1.1.1', 'Explain the concept of the circulatory system, state the function of each part of the system and the health challenges associated with it', '1. Discuss the blood circulatory system in humans and the composition and functions of blood.; 2. Explain the functions of the parts of the circulatory system.; 3. Draw and label the longitudinal section of a mammalian heart.; 4. Describe the prevention and causes of diseases of the circulatory system.; 5. Describe what blood pressure is and ways of managing it.', 190),
('Basic 9', 'Science', 'science', 'Systems', 'The Human Body System', 'B9.3.1.1', 'Demonstrate understanding of the blood circulatory system, health problems associated with the system and its relationship with the respiratory system in humans', 'B9.3.1.1.2', 'Explain the concept of respiration and show how the respiratory and circulatory systems complement each other. (Note that respiration is a chemical reaction that releases carbon dioxide (CO ), water (H O) and energy from glucose 2 2 and oxygen)', '1. Explain the concept of respiration.; 2. Explain how deoxygenated blood from circulation is oxygenated through inhalation for respiration to take place.', 200),
('Basic 9', 'Science', 'science', 'Systems', 'The Solar System', 'B9.3.2.1', 'Demonstrate knowledge of other non- planetary bodies such as comets, asteroids, and their relationship with the solar system', 'B9.3.2.1.1', 'Understand the movement of non-planetary bodies in the solar system', '1. Research for information on the movement of non-planetary bodies in the solar system. E.g. asteroids and comets.; 2. Compare and contrast the movement of the non-planetary bodies in the solar system.', 210),
('Basic 9', 'Science', 'science', 'Systems', 'Ecosystem', 'B9.3.3.1', 'Recognise the interdependence of organisms in an ecosystem and appreciate their interaction to maintain balance in the system', 'B9.3.3.1.1', 'Conduct research into the composition of an ecosystem and discuss how the components depend on each other for survival', '1. Describe how organisms depend on each other in different ecosystems. (You may use pictures, charts and videos).; 2. State the differences between an ecosystem and a habitat.; 3. Construct a food chain and a food web found in an ecosystem.; 4. Predict and justify your predictions on how interferences such as earthquake, volcanic eruptions, hunting, farming, mining, “galamsey,” pollution, pesticides and bush burning will affect the balance in an ecosystem.', 220),
('Basic 9', 'Science', 'science', 'Systems', 'Farming Systems', 'B9.3.4.1', 'Demonstrate knowledge and skills in the preparation of different types of manure from animal and plant waste', 'B9.3.4.1.1', 'List and explain the different plant and animal waste used in preparing different types of manure', '1. List some types of manure used by farmers.; 2. Identify and write down the materials used in preparing manure and their sources .; 3. Categorise manure into those from plant wastes and animal wastes.; 4. Compile a list of plant parts/wastes and animal parts/wastes that are used to prepare manure.; 5. Justify the use of different animal and plant manures (poultry droppings, cow dung, animal parts and carcases, pig dung, human excreta, domestic refuse, leaves, waste fruits, plant parts and shavings, etc) under different soil and climatic conditions.', 230),
('Basic 9', 'Science', 'science', 'Systems', 'Farming Systems', 'B9.3.4.1', 'Demonstrate knowledge and skills in the preparation of different types of manure from animal and plant waste', 'B9.3.4.1.2', 'Demonstrate the preparation of different types of manure', '1. Prepare manure from the different plant and animal wastes.; 2. Discuss the preparation of manure using the plants and animal wastes that are available in a community.', 240),
('Basic 9', 'Science', 'science', 'Systems', 'Farming Systems', 'B9.3.4.1', 'Demonstrate knowledge and skills in the preparation of different types of manure from animal and plant waste', 'B9.3.4.1.3', 'Prepare different types of manure', '1. Treat various plant and animal wastes to generate manure (cleaning/ sorting, curing/composting) in the field or school garden.', 250),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Energy', 'B9.4.1.1', 'Show understanding of the concept of conservation of energy and ways of conserving energy', 'B9.4.1.1.1', 'List the ways to conserve energy', 'ironing in bulk, using energy efficient appliances and switching off appliances when not in use. Exemplar:; 1. Identify and discuss various strategies of conserving energy.', 260),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Energy', 'B9.4.1.1', 'Show understanding of the concept of conservation of energy and ways of conserving energy', 'B9.4.1.1.2', 'Explain the importance of energy conservation in daily life', '1. Research information about energy conservation and discuss its importance to life.', 270),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Energy', 'B9.4.1.2', 'Demonstrate understanding in and the capability to do calculations involving energy', 'B9.4.1.2.1', 'Explain how to calculate energy consumed over a period of time', '1. Calculate electrical energy consumed by the use of electrical appliances in Kilowatt-hour (kWh). P = IV, where P is power, I is current, V is voltage.', 280),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Energy', 'B9.4.1.2', 'Demonstrate understanding in and the capability to do calculations involving energy', 'B9.4.1.2.2', 'Describe how images are formed in cameras', '1. Create a model of a camera and describe how it works to form an image.', 290),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Energy', 'B9.4.1.2', 'Demonstrate understanding in and the capability to do calculations involving energy', 'B9.4.1.2.3', 'Describe the formation of shadows', '1. Discuss the terms umbra and penumbra in relation to the formation of shadows and explain how they are formed.', 300),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Energy', 'B9.4.1.2', 'Demonstrate understanding in and the capability to do calculations involving energy', 'B9.4.1.2.4', 'Demonstrate the formation of an eclipse', '1. Use a model to illustrate how an eclipse is formed,', 310),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Energy', 'B9.4.1.3', 'Evaluate the application of light energy in life', 'B9.4.1.3.1', 'Demonstrate that light changes path when it travels from one medium to a different medium', '1. Carry out a practical activity to show that light bends as it travels from one medium to another. E.g. A rod appears bent in water; deep water appears shallow than its real depth.', 320),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Electricity and Electronics', 'B9.4.2.1', 'Construct electrical circuits and illustrate how electrical energy is transformed into other forms of energy and perform electrical calculations', 'B9.4.2.1.1', 'Demonstrate transformation of electrical energy to other forms of energy in both series and parallel circuits and perform simple calculations involving the flow of current in circuits', '1. Predict the impact of changes in electrical circuits with regards to the output of bulbs. Describe how electrical energy transformation occurs in series and parallel circuits.; 2. Construct simple electrical circuits and measure the voltage, current and resistance.; 3. Calculate the potential difference in a circuit using the formula: V = IR (where I is the current and R the resistance).', 330),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Electricity and Electronics', 'B9.4.2.2', 'Demonstrate an understanding of Forward and Reverse Bias and explain the behaviour of LEDs, Diodes, Resistors and Capacitors in electronic circuits', 'B9.4.2.2.1', 'Describe forward bias and reverse bias and explain the relationship among the components, such as: LEDs, Diodes, Resistors and Capacitors, in an electronic circuit', '1. Explain forward bias and reverse bias in an electronic circuit.; 2. Construct different electronic circuits (the forward and reverse bias), and observe what happens to the LED.; 3. Construct different electronic circuits involving resistors and capacitors and observe what happens to the LED and report on their findings.', 340),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Conversion and Conservation of Energy', 'B9.4.3.1', 'Show an understanding of conversion and conservation of energy and their application to life', 'B9.4.3.1.1', 'Describe how energy can be converted from one form to another and show how conservation of energy occurs', '1. Differentiate between conversion of energy and conservation of energy and show their application to life.', 350),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Conversion and Conservation of Energy', 'B9.4.3.1', 'Show an understanding of conversion and conservation of energy and their application to life', 'B9.4.3.1.2', 'Describe how conversion and conservation of energy are applied in life', '1. Distinguish between energy conversion and conservation using everyday examples.; 2. Identify opportunities to conserve energy and produce a report of your work.', 360),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Force and Motion', 'B9.4.4.1', 'Demonstrate understanding of the concept of pressure and explain how pressure acts in everyday life', 'B9.4.4.1.1', 'Explain the concept of pressure and show how pressure relates to force; perform activities that work on the principle of pressure in the daily lives of humans', '1. Demonstrate the action of pressure through a number of activities such as using drinking straw, pumping car tyres, filling of balloons, water jets at washing bays, etc. to understand the concept of pressure.; 2. Describe the relationship between pressure and force and discuss the application of pressure in everyday life.', 370),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Force and Motion', 'B9.4.4.1', 'Demonstrate understanding of the concept of pressure and explain how pressure acts in everyday life', 'B9.4.4.1.2', 'Demonstrate the application of Newton’s Third Law of motion in life', '1. Predict what happens when: a) a force is exerted on an object. b) There is a reaction from the object c) the force exerted is the same as the reaction of the object.; 2. Perform an activity to justify your predictions.', 380),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Force and Motion', 'B9.4.4.2', 'Demonstrate understanding of Newton’s Laws of motion and ability to apply the laws to solve problems in everyday life', 'B9.4.4.2.1', 'Explain Newton’s Laws of Motion and their applications to daily life', '1. Explain Newton’s Laws of Motion and relate them to momentum.; 2. Demonstrate the application of Newton’s Laws of motion in everyday life.; 3. Derive the formula, f = ma, where f is the force, m the mass of the object, and a, the acceleration, from Newton’s three Laws of Motion and use the formula to calculate the force that a moving mass of body exerts when moving with known acceleration.', 390),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Agricultural Tools', 'B9.4.5.1', 'Demonstrate knowledge and skills in making simple agricultural tools for on-farm activities', 'B9.4.5.1.1', 'Identify materials used in making simple agricultural tools', '1. Describe simple agricultural tools assembled from their environment.; 2. Identify the materials used to make the tools assembled in exemplar 1 and show how the parts are connected.', 400),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Agricultural Tools', 'B9.4.5.1', 'Demonstrate knowledge and skills in making simple agricultural tools for on-farm activities', 'B9.4.5.1.2', 'Discuss and write activities involved in making simple agricultural tools', '1. Describe the activities and processes involved in making different agricultural tools.; 2. Explain the materials, processes, constraints and precautions involved in manufacturing simple agricultural tools.', 410),
('Basic 9', 'Science', 'science', 'Forces and Energy', 'Agricultural Tools', 'B9.4.5.1', 'Demonstrate knowledge and skills in making simple agricultural tools for on-farm activities', 'B9.4.5.1.3', 'Manufacture simple agricultural tools', '1. Produce simple farm tools using materials from the environment.', 420),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Waste Management', 'B9.5.1.1', 'Demonstrate an understanding of the scientific ways of waste management', 'B9.5.1.1.1', 'Investigate the scientific methods used in waste management', '1. Identify scientific methods such as recycling, composting used in waste management.; 2. Explain the scientific principles underlying the methods used in waste management.; 3. Conduct an audit of waste management methods in schools and assess the effectiveness of each.', 430),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Waste Management', 'B9.5.1.2', 'Demonstrate an understanding of the impact of waste on an environment, innovative waste management technologies for sustainable development and waste management practices in Ghana', 'B9.5.1.2.1', 'Describe innovative ways of waste management for sustainable development', '1. Explain the impact of waste produced on the environment.; 2. Identify innovative ways to manage waste for sustainable development.; 3. Describe the types of waste produced within communities in Ghana.; 4. Examine and critique the waste management practices in Ghana identifying positives and negatives and opportunities for improvement.', 440),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Human Health', 'B9.5.2.1', 'Demonstrate knowledge of common non-communicable diseases of humans, their causes, symptoms, effects and prevention', 'B9.5.2.1.1', 'Explain the symptoms, effects and prevention of some non-communicable diseases and analyse the risk factors associated with them', '1. Describe what non-communicable diseases are and determine their common causes.; 2. Identify symptoms, effects and prevention of non-communicable diseases (refer to teachers pack for specific diseases) that are associated with malnutrition, poor working environment and exposure to drugs.; 3. Explain the causes, symptoms, effects and prevention of cancer.; 4. Identify common cancers that affect humans and link them to life style.', 450),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Human Health', 'B9.5.2.2', 'Demonstrate knowledge of selected fungal, diseases of humans, their causes, symptoms, effects and prevention', 'B9.5.2.2.1', 'Explain the nature of fungal diseases with special emphasis on Ringworm/candidiasis/fingernail, and toe nail infection, their causes, symptoms, effects on humans and its prevention', '1. Discuss the nature of fungal diseases.; 2. Search for information and make presentations on ringworm, candidiasis and fungal eye infection diseases their mode of transmission from person to person, community to community and from country to country.; 3. Describe the symptoms, effects and prevention of ringworm, candidiasis and fungal eye infection diseases.; 4. Describe the role of individuals, community members and government in managing ringworm, candidiasis and fungal eye infection diseases.; 5. Design and produce a poster to educate their community members on the incidence and control of named fungal diseases: ringworm, candidiasis and fungal eye infection.', 460),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Human Health', 'B9.5.2.2', 'Demonstrate knowledge of selected fungal, diseases of humans, their causes, symptoms, effects and prevention', 'B9.5.2.2.2', 'Explain the concept of common diseases in an environment', '1. Conduct a survey about common diseases and analyse the findings to show what constitutes a common disease in a community.; 2. Identify causes, symptoms and prevention of common diseases.', 470),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Science and Industry', 'B9.5.3.1', 'Analyse the scientific concepts, principles and processes applied in industries in and outside their community', 'B9.5.3.1.1', 'Investigate the scientific concepts, principles and processes involved in industries in their environment', 'Exemplars: 1. Identify products of industries within and outside their community and describe the process of production.; 2. Investigate and outline scientific concepts, principles and processes underlying the production of common everyday industrial products.', 480),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Science and Industry', 'B9.5.3.2', 'Demonstrate an understanding of the concept of industry, the science underpinning the processes of production in industries the technologies in indigenous industries and western industries', 'B9.5.3.2.1', 'Explain the concept of industry and distinguish between modern and indigenous industries', '1. Identify an industry as individual firms producing the same commodity and give examples of industries in their community.; 2. Describe how technology affects industry and compare the technologies in indigenous and modern industries.', 490),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Science and Industry', 'B9.5.3.2', 'Demonstrate an understanding of the concept of industry, the science underpinning the processes of production in industries the technologies in indigenous industries and western industries', 'B9.5.3.2.2', 'Examine indigenous industries in their communities and show the scientific processes in the stages of production', '1. Discuss indigenous industries in their communities and identify the scientific processes, concepts and principles underlying the stages of production in the industries.; 2. Identify indigenous practices at home, school and the community and the science involved in the practices.', 500),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Climate Change and Green Economy', 'B9.5.4.1', 'Demonstrate an understanding of the natural and human factors that influence climate change and a green economy', 'B9.5.4.1.1', 'Examine various natural and human factors that influence climate change and green economy in their localities', '1. Identify the natural factors that influence climate change.; 2. Describe ways of minimising human activities that influence climate change.; 3. Compare natural and human factors that influence climate change and green economy.', 510),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Climate Change and Green Economy', 'B9.5.4.2', 'Evaluate the effectiveness of initiatives that address the issue of climate change and green economy in Ghana and the world at large', 'B9.5.4.2.1', 'Assess data on climate change and green economy actions/ activities globally including Ghana and other countries', '1. Research into climate change and green economy actions in Ghana.; 2. Access climate change and green economy actions in other countries.; 3. Compare and contrast climate change and green economy actions in Ghana and other countries.; 4. Identify and write the effective initiatives that address climate change and green economy issues in Ghana and other countries.; 5. Prescribe with reasons best practices to serve as possible solutions', 520),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Climate Change and Green Economy', 'B9.5.5.1', 'Demonstrate knowledge and skills in the use of plant roots, stems, leaves, flowers, and fruits for agricultural and non-agricultural purposes', 'B9.5.5.1.1', 'Show and list the uses of different plant parts for agricultural and non-agricultural purposes', '1. Identify plant parts that are used for agricultural and non-agricultural purposes.; 2. Describe how plant parts are used for agricultural and non- agricultural purposes.; 3. List the uses of plant parts for agricultural purposes (such as planting, tools, animal housing, animal feed, soil improvement, pest and disease control, etc.).; 4. List the uses of plant parts for non-agricultural purposes (such as herbal medicine, construction of houses, bridges and furniture, artefacts, ceremonies, rituals, education, etc.).', 530),
('Basic 9', 'Science', 'science', 'Humans and the Environment', 'Climate Change and Green Economy', 'B9.5.5.1', 'Demonstrate knowledge and skills in the use of plant roots, stems, leaves, flowers, and fruits for agricultural and non-agricultural purposes', 'B9.5.5.1.2', 'Demonstrate the use of different plant parts for agricultural and non-agricultural purposes', '1. Create agricultural materials from different plant parts that are used to carry out agricultural activities.; 2. Create non-agricultural materials from different plant parts to carry out non-agricultural activities.', 540),
('Basic 9', 'Social Studies', 'social studies', 'Environment', 'Environmental Issues', 'B9.1.1.1', 'Demonstrate skills in dealing with environmental challenges', 'B9.1.1.1.1', 'Examine air pollution as an environmental challenge', '1. Explain what air pollution means.; 2. Identify activities in the environment that lead to air pollution, including fumes from vehicles, industry and smoke from fires.', 10),
('Basic 9', 'Social Studies', 'social studies', 'Environment', 'Environmental Issues', 'B9.1.1.2', 'Evaluate the sources and ways of conserving energy', 'B9.1.1.2.1', 'Assess global sources and the means of conserving energy', '1. Identify global energy sources and conservation in countries such as Ghana, United Kingdom, Germany.; 2. With the use of the Internet, research alternative energy sources and do a presentation in class.; 3. Discuss gender issues related to energy production, supply and usage (Access to energy resources affects quality of life; some segments of the society are more vulnerable to impact of energy choices than others).; 4. Describe the processes and devices for measuring and metering energy consumption.; 5. In groups, create posters on the advantages of energy conservation to educate others in the community, including saving money, making the most of our scarce energy resources and reducing air pollution.', 20),
('Basic 9', 'Social Studies', 'social studies', 'Environment', 'Our Natural and Human Resources', 'B9.1.4.1', 'Investigate the natural and human resources around us', 'B9.1.4.1.1', 'Examine the importance of natural resources to the development of Ghana', '1. Explain what is meant by natural resources.; 2. Through the use of videos or pictures, identify the natural resources of the country, including renewable (for example timber) and non- renewable resources (such as gold, bauxite and oil).; 3. On the map of Ghana, show the location of the natural resources.; 4. Discuss efficient ways of exploiting natural resources.; 5. Explain the importance of natural resources for the development of the country. 6. Discuss the difficulty in exploiting natural resources effectively, including low level of technology, limited technical expertise and limited capital resources.', 30),
('Basic 9', 'Social Studies', 'social studies', 'Environment', 'Our Natural and Human Resources', 'B9.1.4.1', 'Investigate the natural and human resources around us', 'B9.1.4.1.2', 'Evaluate the importance of human resources to the development of Ghana', '1. Explain what is meant by human resource.', 40),
('Basic 9', 'Social Studies', 'social studies', 'Family Life', 'The Family', 'B9.2.2.1', 'Evaluate the institution of marriage in Ghana', 'B9.2.2.1.1', 'Examine the importance of marriage as a social institution in Ghana', '1. Explain the concept of marriage as a social institution (other social institutions include the family and religious sects).; 2. Discuss ways of contracting marriages in Ghana.; 3. Identify the ways in which marriage is important as a social institution, including providing a stable, loving setting for children to be brought up and helping to provide economic support for parents.', 50),
('Basic 9', 'Social Studies', 'social studies', 'Family Life', 'The Family', 'B9.2.2.2', 'Assess the need for responsible parenting in the family', 'B9.2.2.2.1', 'Examine the importance of responsible parenting within the family system', '1. Explain the concepts: i. Parenthood ii. Parenting; 2. Differentiate parenthood from parenting.; 3. Discuss the responsibilities of parents including providing food, clothes, shelter and a loving and stable environment for the upbringing of children.; 4. Discuss inappropriate parenting behaviour and its consequences, including failure to provide the basic needs of children,. For example, drunkenness.', 60),
('Basic 9', 'Social Studies', 'social studies', 'Family Life', 'Population', 'B9.2.4.1', 'Analyse the population structure in Ghana and its related issues', 'B9.2.4.1.1', 'Assess population structure in Ghana and its associated development issues', '1. Recap on Basic 8 work on the population structure in Ghana. With the use of the Internet or a chart examine the structure of the Ghanaian population.; 2. In groups, analyse the effects of rapid population growth on the family, the community and the nation.', 70),
('Basic 9', 'Social Studies', 'social studies', 'Sense of Purpose', 'Culture and National Identity', 'B9.3.3.1', 'Evaluate the place of culture in national identity', 'B9.3.3.1.1', 'Assess the significance of symbols, music and ceremonies in promoting national identity', '1. Explain the concept of national identity.; 2. Sing patriotic songs and discuss how songs promote national identity.; 3. With the use of videos or pictures, identify some national and traditional symbols and discuss their features and significance. For example, the National Flag, Coat of Arms, the Staff of Office of the President, the Mace, Adinkra and other Ghanaian symbols', 80),
('Basic 9', 'Social Studies', 'social studies', 'Law and Order', 'The 1992 Constitution', 'B9.4.3.1', 'Assess the relevance of the 1992 Constitution', 'B9.4.3.1.1', 'Examine the 1992 Constitution and its significance to national development', '1. Explain the meaning of a constitution.; 2. Outline the main features of the 1992 Constitution.; 3. Use videos or pictures to identify the functions of the three main organs of government (the legislature, the executive and the judiciary).', 90),
('Basic 9', 'Social Studies', 'social studies', 'Law and Order', 'The 1992 Constitution', 'B9.4.3.1', 'Assess the relevance of the 1992 Constitution', 'B9.4.3.1.2', 'Discuss the rights of the child as enshrined in the 1992 Constitution', '1. Explain the concepts of child rights.; 2. Examine the provisions of child rights in the 1992 Constitution.; 3. Invite a resource person to discuss the need for children’s rights.', 100),
('Basic 9', 'Social Studies', 'social studies', 'Law and Order', 'Peace and Security in Our Nation', 'B9.4.4.1', 'Assess the role of peace and security in national development', 'B9.4.4.1.1', 'Examine the relevance of peace and security in our community', '1. Explain the concepts of peace and security.; 2. Discuss ways of promoting peace and security.; 3. With the use of video and pictures, compare a country destroyed by conflict and another that has enjoyed a long period of peace.', 110),
('Basic 9', 'Social Studies', 'social studies', 'Law and Order', 'Promoting Democracy and Political Stability', 'B9.4.5.1', 'Show understanding of how to promote democracy and political stability', 'B9.4.5.1.1', 'Examine election as a way of promoting democracy and political stability', '1. Explain the concepts of democracy and election.; 2. Examine the role of free and fair elections in promoting democracy.', 120),
('Basic 9', 'Social Studies', 'social studies', 'Law and Order', 'Promoting Democracy and Political Stability', 'B9.4.5.2', 'Demonstrate understanding of the District Assembly concept in Ghana', 'B9.4.5.2.1', 'Examine the role of the District Assembly in promoting decentralisation', '1. Explain the concept of decentralisation.; 2. Describe the structure of the District Assembly as a decentralised arm of government.; 3. Examine the role of District Assemblies in the development of the districts.', 130),
('Basic 9', 'Social Studies', 'social studies', 'Law and Order', 'Promoting Democracy and Political Stability', 'B9.4.5.3', 'Evaluate the importance of political stability in Ghana’s development', 'B9.4.5.3.1', 'Assess the significance of political stability in national development', '1. Explain political stability.', 140),
('Basic 9', 'Social Studies', 'social studies', 'Socio-economic Development', 'Financial and Investment Issues', 'B9.5.2.1', 'Show understanding of the provisions under National Pensions Act 766 and PNDC Law 247', 'B9.5.2.1.1', 'Exhibit knowledge on pension rights under National Pensions Act 766 and PNDC Law 247', '1. Discuss the provisions under National Pensions Act 766.; 2. In small groups, do a presentation on the provisions under PNDC Law 247.', 150),
('Basic 9', 'Social Studies', 'social studies', 'Socio-economic Development', 'Science and Technology', 'B9.5.4.1', 'Analyse the contribution of science and technology to national development', 'B9.5.4.1.1', 'Examine how science and technology can be used to promote development', '1. Explain the concepts: i. Science ii. Technology; 2. Examine the difference(s) between ‘Science’ and ‘Technology’.; 3. Discuss how science and technology can be used for development and production in Ghana.', 160),
('Basic 9', 'Social Studies', 'social studies', 'Nationhood', 'The Republics', 'B9.6.2.1', 'Demonstrate understanding that Ghana had two republics between 1979 and 2000', 'B9.6.2.1.1', 'Explain how the Third Republic came into being (1979-1981)', '1. Use the internet, print media and oral sources to find out how the Third Republic was established.; 2. Identify the main political parties that took part in the June 1979 elections and their respective candidates.; 3. Discuss the outcome of the June 1979 elections.; 4. With the use of Internet sources, dramatise the handing over of power from the AFRC to Dr Hilla Liman’s People’s National Party.', 170),
('Basic 9', 'Social Studies', 'social studies', 'Nationhood', 'The Republics', 'B9.6.2.1', 'Demonstrate understanding that Ghana had two republics between 1979 and 2000', 'B9.6.2.1.2', 'Explain political developments under the Third Republic', '1. Identify the main features of the Third Republican Constitution, including the prohibition of a one-party state, limitation on the influence of the armed forces and the police.; 2. Discuss the impact of the Third Republican Constitution on the political development of the country, including the civilisation of the armed forces, promotion of multiparty system and national integration.; 3. Compare the features of the Second and Third Republican Constitution', 180),
('Basic 9', 'Social Studies', 'social studies', 'Nationhood', 'The Republics', 'B9.6.2.1', 'Demonstrate understanding that Ghana had two republics between 1979 and 2000', 'B9.6.2.1.3', 'Explain how the Fourth Republic came into being', '1. Use the Internet, print media and oral sources to find out how the Fourth Republic was established.; 2. Discuss the outcome of the 28 April 1992 referendum.', 190);
